'use strict';
const assert = require('node:assert/strict');
const {load,compare,scoreResults} = require('./score.cjs');
const data=load(), report=compare(data);
assert.equal(report.firstRoundBO1[0].a,'9z');
assert.equal(report.slotDisagreements.length,6);
assert.deepEqual(report.pleyVsPublished.map(entry=>entry.team),
  ['PARIVISION','FaZe','Eternal Fire','M80','Imperial','FlyQuest','Lynn Vision']);

// Transpose an already finished bracket by seed solely to exercise the scorer.
// Nothing generated by this test is a Singapore result or written to the archive.
const fixture=require('../fixtures/fixtures.json').austin;
const localName = name=>data.teams[fixture.seeds.indexOf(name)];
const rounds=fixture.rounds.map(r=>r.map(pair=>pair.map(localName)));
const label=name=>name==='GOSH'?'BC.Game':name==='PARIVISION'?'PVISION':name;
const input={stage:report.stage,source:'https://example.org/test-fixture',rounds:rounds.map(r=>r.map(pair=>pair.map(label)))};
const scored=scoreResults(data,input);
assert.equal(scored.verifiedPairings,33);
const w=Object.fromEntries(data.teams.map(t=>[t,0])), l={...w};
for(const [winner,loser] of rounds.flat()) { w[winner]++; l[loser]++; }
for(const [id,card] of [['originalRecommended',data.localCard],['recommended',data.currentCard],['earlierStageChallenger',data.challengerCard],['CSGOTradeUp',data.publicCard],['Pley',data.pleyCard]]) {
  const hits=data.teams.filter((t,i)=>card[i]===0?w[t]===3&&l[t]===0:
    card[i]===1?w[t]===3&&l[t]>0:card[i]===2?w[t]===0:false).length;
  assert.equal(scored.completedStage[id].hits,hits);
  assert.equal(scored.completedStage[id].passed,hits>=5);
}
for(const result of Object.values(scored.stageProbabilityErrors)) {
  assert.equal(result.bo1.games,20);assert.equal(result.bo3.games,13);
  for(const format of Object.values(result)) assert(format.brier>=0 && format.brier<1 && format.logLoss>0);
}
for(const [id,field] of [['recommended','localP'],['DAKEbits','publicP']]) {
  let sum=0;
  for(const [winner,loser] of rounds[0]) {
    const row=data.roundOne.find(m=>[winner,loser].includes(m.a)&&[winner,loser].includes(m.b));
    sum+=(row[field]-Number(winner===row.a))**2;
  }
  assert.ok(Math.abs(scored.firstRoundBO1[id].brier-sum/8)<1e-12);
}
assert.throws(()=>scoreResults(data,{...input,stage:'stage-2'}));
assert.throws(()=>scoreResults(data,{...input,rounds:rounds.slice(0,1)}));
const invalid=structuredClone(rounds);
invalid[0][1]=invalid[0][0];
assert.throws(()=>scoreResults(data,{...input,rounds:invalid}));
console.log('Verified sealed inputs, 8 BO1 probabilities, all 2/6/2 tickets, 33-pairing replay, scoring and invalid input rejection.');
